class GeneratedInstanceTypeTests : public ::testing::Test
{
protected:
  static void SetUpTestSuite()
  {
    const auto cfg = ApplicationConfig::load_default();
    const auto limits = make_encoding_limits(cfg);

    threadPool.emplace();
    addressSpace.emplace(AddressSpace::create("uri:test", threadPool->get_executor()));

    StructureFactory structureFactory;
    auto lookupFn = namespace_array_utils::get_index_lookup_function(*addressSpace);
    const CodecNamespaceContext nsConfig{std::move(lookupFn), {}, {}, {}};
    register_ua_data_types_with_factory(nsConfig, &structureFactory, &structureFactory);

    FileStream inputStream{"NodeSet2.xml"};
    inputStream.open_for_read();
    auto nodeSets = Parser::parse(limits,
      inputStream,
      structureFactory,
      addressSpace->namespace_array(),
      addressSpace->server_array(),
      Parser::GetDependentModelCallback{});

    auto importer = ImportEngine::create(limits, *addressSpace, nodeSets, {});
    importer->import_all_sync({}, {});
  }

  static void TearDownTestSuite()
  {
    addressSpace.reset();
    if (threadPool)
      threadPool->join();
    threadPool.reset();
  }

  static optional<boost::asio::thread_pool> threadPool;
  static optional<AddressSpace> addressSpace;
};

optional<boost::asio::thread_pool> GeneratedInstanceTypeTests::threadPool;
optional<AddressSpace> GeneratedInstanceTypeTests::addressSpace;

namespace
{

/// Registers a Part 19 dictionary namespace in the suite's shared address space unless it already is.
void register_dictionary_namespace(AddressSpace& space, std::string_view uri)
{
  try
  {
    (void)space.namespace_array().get_namespace_index(uri);
    return;
  }
  catch (const UaException&)
  {}
  (void)space.add_namespace_sync(space.create_namespace(uri, {}));
}

}  // namespace

TEST_F(GeneratedInstanceTypeTests, AcknowledgeableCondition_DefaultConstruction)
{
  AcknowledgeableCondition obj;
  (void)obj;
}

TEST_F(GeneratedInstanceTypeTests, AcknowledgeableCondition_CreateAndAttach)
{
  auto createResult = AcknowledgeableCondition::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestAcknowledgeableCondition"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = AcknowledgeableCondition::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = AcknowledgeableCondition::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = AcknowledgeableCondition::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestAcknowledgeableConditionThrowing"},
    {});
  (void)created2;
}

