TEST_F(GeneratedInstanceTypeTests, ApplicationConfigurationFile_UnattachedAccessorsFailClosed)
{
  ApplicationConfigurationFile obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_available_networks_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_available_networks_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_max_endpoints_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_max_endpoints_sync(uint16_t{12345}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_max_certificate_groups_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_max_certificate_groups_sync(uint16_t{12345}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_certificate_types_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_certificate_types_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_certificate_group_purposes_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_certificate_group_purposes_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_supported_data_type_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_supported_data_type_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_size_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_size_sync(uint64_t{1234567}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_writable_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_writable_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_user_writable_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_user_writable_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_open_count_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_open_count_sync(uint16_t{12345}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_mime_type_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_mime_type_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_max_byte_string_length_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_max_byte_string_length_sync(uint32_t{123456}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_last_modified_time_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_last_modified_time_sync(DateTime::now()).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_available_networks_property_sync().status_code();
  (void)obj.try_available_ports_property_sync().status_code();
  (void)obj.try_max_endpoints_property_sync().status_code();
  (void)obj.try_max_certificate_groups_property_sync().status_code();
  (void)obj.try_security_policy_uris_property_sync().status_code();
  (void)obj.try_user_token_types_property_sync().status_code();
  (void)obj.try_certificate_types_property_sync().status_code();
  (void)obj.try_certificate_group_purposes_property_sync().status_code();
  (void)obj.try_last_update_time_property_sync().status_code();
  (void)obj.try_current_version_property_sync().status_code();
  (void)obj.try_activity_timeout_property_sync().status_code();
  (void)obj.try_supported_data_type_property_sync().status_code();
  (void)obj.try_size_property_sync().status_code();
  (void)obj.try_writable_property_sync().status_code();
  (void)obj.try_user_writable_property_sync().status_code();
  (void)obj.try_open_count_property_sync().status_code();
  (void)obj.try_mime_type_property_sync().status_code();
  (void)obj.try_max_byte_string_length_property_sync().status_code();
  (void)obj.try_last_modified_time_property_sync().status_code();
}

