TEST_F(GeneratedInstanceTypeTests, ApplicationConfigurationFolder_CreateAndAttach)
{
  auto createResult = ApplicationConfigurationFolder::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestApplicationConfigurationFolder"},
    {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = ApplicationConfigurationFolder::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = ApplicationConfigurationFolder::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = ApplicationConfigurationFolder::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestApplicationConfigurationFolderThrowing"},
    {});
  (void)created2;
}

