TEST_F(GeneratedInstanceTypeTests, AuditConditionCommentEvent_CreateAndAttach)
{
  auto createResult = AuditConditionCommentEvent::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestAuditConditionCommentEvent"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = AuditConditionCommentEvent::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = AuditConditionCommentEvent::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = AuditConditionCommentEvent::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestAuditConditionCommentEventThrowing"},
    {});
  (void)created2;
}

