TEST_F(GeneratedInstanceTypeTests, AuditConditionConfirmEvent_CreateAndAttach)
{
  auto createResult = AuditConditionConfirmEvent::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestAuditConditionConfirmEvent"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = AuditConditionConfirmEvent::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = AuditConditionConfirmEvent::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = AuditConditionConfirmEvent::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestAuditConditionConfirmEventThrowing"},
    {});
  (void)created2;
}

