TEST_F(GeneratedInstanceTypeTests, AuditConditionEnableEvent_CreateAndAttach)
{
  auto createResult = AuditConditionEnableEvent::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestAuditConditionEnableEvent"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = AuditConditionEnableEvent::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = AuditConditionEnableEvent::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = AuditConditionEnableEvent::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestAuditConditionEnableEventThrowing"},
    {});
  (void)created2;
}

