TEST_F(GeneratedInstanceTypeTests, AuditConditionEvent_CreateAndAttach)
{
  auto createResult = AuditConditionEvent::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestAuditConditionEvent"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = AuditConditionEvent::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = AuditConditionEvent::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = AuditConditionEvent::create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestAuditConditionEventThrowing"}, {});
  (void)created2;
}

