TEST_F(GeneratedInstanceTypeTests, AuditConditionShelvingEvent_CreateAndAttach)
{
  auto createResult = AuditConditionShelvingEvent::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestAuditConditionShelvingEvent"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = AuditConditionShelvingEvent::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = AuditConditionShelvingEvent::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = AuditConditionShelvingEvent::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestAuditConditionShelvingEventThrowing"},
    {});
  (void)created2;
}

