TEST_F(GeneratedInstanceTypeTests, DialogCondition_Children)
{
  InstantiationOptions optionsWithAllOptionals;
  optionsWithAllOptionals.optionalChildFilter = [](const ChildFilterInfo&)
  {
    return true;
  };
  auto createResult = DialogCondition::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestDialogConditionKids"},
    optionsWithAllOptionals);
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();

  // Typed child-object / data-variable accessors.
  {
    auto r = obj.try_enabled_state_sync();
    (void)r.status_code();
    try
    {
      (void)obj.enabled_state_sync();
    }
    catch (...)
    {}
  }
  {
    auto r = obj.try_dialog_state_sync();
    (void)r.status_code();
    try
    {
      (void)obj.dialog_state_sync();
    }
    catch (...)
    {}
  }

  // Method handler registration + method-accessor lookup.
  {
    DialogCondition::RespondHandler handler =
      [](const MethodCall&, const DialogCondition::RespondInputArguments&) -> MethodResult<>
    {
      return {};
    };
    auto sh = obj.try_set_respond_handler_sync(std::move(handler));
    (void)sh.status_code();
    DialogCondition::RespondAsyncHandler asyncHandler =
      [](const MethodCall&, const DialogCondition::RespondInputArguments&, MethodResultCallback<> complete)
    {
      complete({});
    };
    auto ash = obj.try_set_respond_handler_sync(std::move(asyncHandler));
    (void)ash.status_code();
    auto ma = obj.try_respond_method_sync();
    (void)ma.status_code();
  }
  {
    DialogCondition::Respond2Handler handler =
      [](const MethodCall&, const DialogCondition::Respond2InputArguments&) -> MethodResult<>
    {
      return {};
    };
    auto sh = obj.try_set_respond2_handler_sync(std::move(handler));
    (void)sh.status_code();
    DialogCondition::Respond2AsyncHandler asyncHandler =
      [](const MethodCall&, const DialogCondition::Respond2InputArguments&, MethodResultCallback<> complete)
    {
      complete({});
    };
    auto ash = obj.try_set_respond2_handler_sync(std::move(asyncHandler));
    (void)ash.status_code();
    auto ma = obj.try_respond2_method_sync();
    (void)ma.status_code();
  }
}

TEST_F(GeneratedInstanceTypeTests, DialogCondition_UnattachedAccessorsFailClosed)
{
  DialogCondition obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_prompt_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_prompt_sync(LocalizedText{"en", "test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_response_option_set_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_response_option_set_sync(LocalizedText{"en", "test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_default_response_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_default_response_sync(int32_t{123456}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_ok_response_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_ok_response_sync(int32_t{123456}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_cancel_response_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_cancel_response_sync(int32_t{123456}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_last_response_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_last_response_sync(int32_t{123456}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_condition_class_id_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_condition_class_id_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_condition_class_name_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_condition_class_name_sync(LocalizedText{"en", "test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_condition_sub_class_id_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_condition_sub_class_id_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_condition_sub_class_name_sync().status_code().is_bad());
  EXPECT_TRUE(
    obj.try_write_condition_sub_class_name_sync(LocalizedText{"en", "test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_condition_name_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_condition_name_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_branch_id_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_branch_id_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_retain_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_retain_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_supports_filtered_retain_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_supports_filtered_retain_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_client_user_id_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_client_user_id_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_event_id_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_event_id_sync(ByteString{1, 2, 3}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_event_type_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_event_type_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_source_node_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_source_node_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_source_name_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_source_name_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_message_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_message_sync(LocalizedText{"en", "test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_severity_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_severity_sync(uint16_t{12345}).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_prompt_property_sync().status_code();
  (void)obj.try_response_option_set_property_sync().status_code();
  (void)obj.try_default_response_property_sync().status_code();
  (void)obj.try_ok_response_property_sync().status_code();
  (void)obj.try_cancel_response_property_sync().status_code();
  (void)obj.try_last_response_property_sync().status_code();
  (void)obj.try_condition_class_id_property_sync().status_code();
  (void)obj.try_condition_class_name_property_sync().status_code();
  (void)obj.try_condition_sub_class_id_property_sync().status_code();
  (void)obj.try_condition_sub_class_name_property_sync().status_code();
  (void)obj.try_condition_name_property_sync().status_code();
  (void)obj.try_branch_id_property_sync().status_code();
  (void)obj.try_retain_property_sync().status_code();
  (void)obj.try_supports_filtered_retain_property_sync().status_code();
  (void)obj.try_client_user_id_property_sync().status_code();
  (void)obj.try_event_id_property_sync().status_code();
  (void)obj.try_event_type_property_sync().status_code();
  (void)obj.try_source_node_property_sync().status_code();
  (void)obj.try_source_name_property_sync().status_code();
  (void)obj.try_time_property_sync().status_code();
  (void)obj.try_receive_time_property_sync().status_code();
  (void)obj.try_local_time_property_sync().status_code();
  (void)obj.try_message_property_sync().status_code();
  (void)obj.try_severity_property_sync().status_code();

  // Typed child-object / data-variable handle lookups.
  (void)obj.try_enabled_state_sync().status_code();
  (void)obj.try_dialog_state_sync().status_code();

  // Method-accessor lookups.
  (void)obj.try_respond_method_sync().status_code();
  (void)obj.try_respond2_method_sync().status_code();
}

TEST_F(GeneratedInstanceTypeTests, DialogCondition_Method_Respond)
{
  auto createResult = DialogCondition::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestDialogConditionMethodRespond"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();

  std::atomic<bool> handlerCalled{false};
  DialogCondition::RespondHandler handler =
    [&](const MethodCall&, const DialogCondition::RespondInputArguments& in) -> MethodResult<>
  {
    handlerCalled = true;
    auto expected_in_SelectedResponse = int32_t{123456};
    EXPECT_EQ(in.selectedResponse, expected_in_SelectedResponse);
    return {};
  };

  auto setRes = obj.try_set_respond_handler_sync(std::move(handler));
  ASSERT_TRUE(setRes.is_good()) << "set handler failed: 0x" << std::hex << setRes.status_code().as_uint32();

  auto maRes = obj.try_respond_method_sync();
  ASSERT_TRUE(maRes.is_good()) << "method accessor lookup failed: 0x" << std::hex
                               << maRes.status_code().as_uint32();
  auto ma = std::move(maRes).value();

  CallMethodRequest req;
  req.object_id() = obj.node_id();
  req.method_id() = ma.get_node_id();
  req.input_arguments().resize(1);
  req.input_arguments()[0] = Variant{int32_t{123456}};

  auto callRes = ma.try_call_sync(req);
  ASSERT_TRUE(callRes.is_good()) << "call failed: 0x" << std::hex << callRes.status_code().as_uint32();
  EXPECT_TRUE(handlerCalled.load());
}

