TEST_F(GeneratedInstanceTypeTests, DiscreteAlarm_DefaultConstruction)
{
  DiscreteAlarm obj;
  (void)obj;
}

TEST_F(GeneratedInstanceTypeTests, DiscreteAlarm_CreateAndAttach)
{
  auto createResult = DiscreteAlarm::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestDiscreteAlarm"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = DiscreteAlarm::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = DiscreteAlarm::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = DiscreteAlarm::create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestDiscreteAlarmThrowing"}, {});
  (void)created2;
}

