{
  EccBrainpoolP256r1ApplicationCertificate obj;
  (void)obj;
}

TEST_F(GeneratedInstanceTypeTests, EccBrainpoolP256r1ApplicationCertificate_CreateAndAttach)
{
  auto createResult = EccBrainpoolP256r1ApplicationCertificate::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestEccBrainpoolP256r1ApplicationCertificate"},
    {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = EccBrainpoolP256r1ApplicationCertificate::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = EccBrainpoolP256r1ApplicationCertificate::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = EccBrainpoolP256r1ApplicationCertificate::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestEccBrainpoolP256r1ApplicationCertificateThrowing"},
    {});
  (void)created2;
}

