    EXPECT_TRUE(wr.is_good()) << "setpoint_node write failed: 0x" << std::hex << wr.status_code().as_uint32();
    auto rd = obj.try_read_setpoint_node_sync();
    EXPECT_TRUE(rd.is_good()) << "setpoint_node read failed: 0x" << std::hex << rd.status_code().as_uint32();
