TEST_F(GeneratedInstanceTypeTests, ExclusiveLimitAlarm_CreateAndAttach)
{
  auto createResult = ExclusiveLimitAlarm::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestExclusiveLimitAlarm"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = ExclusiveLimitAlarm::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = ExclusiveLimitAlarm::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = ExclusiveLimitAlarm::create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestExclusiveLimitAlarmThrowing"}, {});
  (void)created2;
}

