TEST_F(GeneratedInstanceTypeTests, ExclusiveLimitStateMachine_CreateAndAttach)
{
  auto createResult = ExclusiveLimitStateMachine::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestExclusiveLimitStateMachine"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = ExclusiveLimitStateMachine::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = ExclusiveLimitStateMachine::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = ExclusiveLimitStateMachine::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestExclusiveLimitStateMachineThrowing"},
    {});
  (void)created2;
}

