TEST_F(GeneratedInstanceTypeTests, File_UnattachedAccessorsFailClosed)
{
  File obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_size_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_size_sync(uint64_t{1234567}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_writable_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_writable_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_user_writable_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_user_writable_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_open_count_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_open_count_sync(uint16_t{12345}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_mime_type_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_mime_type_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_max_byte_string_length_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_max_byte_string_length_sync(uint32_t{123456}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_last_modified_time_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_last_modified_time_sync(DateTime::now()).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_size_property_sync().status_code();
  (void)obj.try_writable_property_sync().status_code();
  (void)obj.try_user_writable_property_sync().status_code();
  (void)obj.try_open_count_property_sync().status_code();
  (void)obj.try_mime_type_property_sync().status_code();
  (void)obj.try_max_byte_string_length_property_sync().status_code();
  (void)obj.try_last_modified_time_property_sync().status_code();

  // Method-accessor lookups.
  (void)obj.try_open_method_sync().status_code();
  (void)obj.try_close_method_sync().status_code();
  (void)obj.try_read_method_sync().status_code();
  (void)obj.try_write_method_sync().status_code();
  (void)obj.try_get_position_method_sync().status_code();
  (void)obj.try_set_position_method_sync().status_code();
}

TEST_F(GeneratedInstanceTypeTests, File_Method_Open)
{
  auto createResult = File::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestFileMethodOpen"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();

  std::atomic<bool> handlerCalled{false};
  File::OpenHandler handler = [&](const MethodCall&,
                                const File::OpenInputArguments& in) -> MethodResult<File::OpenOutputArguments>
  {
    handlerCalled = true;
    auto expected_in_Mode = uint8_t{123};
    EXPECT_EQ(in.mode, expected_in_Mode);
    File::OpenOutputArguments out;
    out.fileHandle = uint32_t{777777};
    return out;
  };

  auto setRes = obj.try_set_open_handler_sync(std::move(handler));
  ASSERT_TRUE(setRes.is_good()) << "set handler failed: 0x" << std::hex << setRes.status_code().as_uint32();

  auto maRes = obj.try_open_method_sync();
  ASSERT_TRUE(maRes.is_good()) << "method accessor lookup failed: 0x" << std::hex
                               << maRes.status_code().as_uint32();
  auto ma = std::move(maRes).value();

  CallMethodRequest req;
  req.object_id() = obj.node_id();
  req.method_id() = ma.get_node_id();
  req.input_arguments().resize(1);
  req.input_arguments()[0] = Variant{uint8_t{123}};

  auto callRes = ma.try_call_sync(req);
  ASSERT_TRUE(callRes.is_good()) << "call failed: 0x" << std::hex << callRes.status_code().as_uint32();
  EXPECT_TRUE(handlerCalled.load());
  const auto& outArgs = callRes.value().output_arguments();
  ASSERT_EQ(outArgs.size(), 1u);
  auto expected_out_FileHandle = uint32_t{777777};
  EXPECT_EQ(outArgs[0].as<uint32_t>(), expected_out_FileHandle);
}

