TEST_F(GeneratedInstanceTypeTests, FiniteStateVariable_Properties)
{
  InstantiationOptions optionsWithAllOptionals;
  optionsWithAllOptionals.optionalChildFilter = [](const ChildFilterInfo&)
  {
    return true;
  };
  auto createResult = FiniteStateVariable::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestFiniteStateVariableProps"},
    optionsWithAllOptionals,
    {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();

  // Untyped Property handle lookup - exercises the find-by-browse-name
  // path for every declared property.
  {
    auto h = obj.try_id_property_sync();
    (void)h.status_code();
    try
    {
      (void)obj.id_property_sync();
    }
    catch (...)
    {}
  }
  {
    auto h = obj.try_name_property_sync();
    (void)h.status_code();
    try
    {
      (void)obj.name_property_sync();
    }
    catch (...)
    {}
  }
  {
    auto h = obj.try_number_property_sync();
    (void)h.status_code();
    try
    {
      (void)obj.number_property_sync();
    }
    catch (...)
    {}
  }
  {
    auto h = obj.try_effective_display_name_property_sync();
    (void)h.status_code();
    try
    {
      (void)obj.effective_display_name_property_sync();
    }
    catch (...)
    {}
  }

  // Typed read/write - every property (mandatory + optional) is
  // instantiated by the optional-inclusive create above, so we can
  // assert write+read both succeed and the read returns the sentinel.
  {
    auto sentinel = NodeId{1234};
    auto wr = obj.try_write_id_sync(sentinel);
    EXPECT_TRUE(wr.is_good()) << "id write failed: 0x" << std::hex << wr.status_code().as_uint32();
    auto rd = obj.try_read_id_sync();
    EXPECT_TRUE(rd.is_good()) << "id read failed: 0x" << std::hex << rd.status_code().as_uint32();
    if (wr.is_good() && rd.is_good())
    {
      EXPECT_EQ(rd.value(), sentinel);
      // Throwing variants (no try_ prefix): same write+read
      // round-trip. Only reached when the try_ variants are good,
      // so these never throw here; a regression that broke the
      // throwing path would surface as a thrown UaException.
      obj.write_id_sync(sentinel);
      EXPECT_EQ(obj.read_id_sync(), sentinel);
    }
  }
  {
    auto sentinel = QualifiedName{0, "test"};
    auto wr = obj.try_write_name_sync(sentinel);
    EXPECT_TRUE(wr.is_good()) << "name write failed: 0x" << std::hex << wr.status_code().as_uint32();
    auto rd = obj.try_read_name_sync();
    EXPECT_TRUE(rd.is_good()) << "name read failed: 0x" << std::hex << rd.status_code().as_uint32();
    if (wr.is_good() && rd.is_good())
    {
      EXPECT_EQ(rd.value(), sentinel);
      // Throwing variants (no try_ prefix): same write+read
      // round-trip. Only reached when the try_ variants are good,
      // so these never throw here; a regression that broke the
      // throwing path would surface as a thrown UaException.
      obj.write_name_sync(sentinel);
      EXPECT_EQ(obj.read_name_sync(), sentinel);
    }
  }
  {
    auto sentinel = uint32_t{123456};
    auto wr = obj.try_write_number_sync(sentinel);
    EXPECT_TRUE(wr.is_good()) << "number write failed: 0x" << std::hex << wr.status_code().as_uint32();
    auto rd = obj.try_read_number_sync();
    EXPECT_TRUE(rd.is_good()) << "number read failed: 0x" << std::hex << rd.status_code().as_uint32();
    if (wr.is_good() && rd.is_good())
    {
      EXPECT_EQ(rd.value(), sentinel);
      // Throwing variants (no try_ prefix): same write+read
      // round-trip. Only reached when the try_ variants are good,
      // so these never throw here; a regression that broke the
      // throwing path would surface as a thrown UaException.
      obj.write_number_sync(sentinel);
      EXPECT_EQ(obj.read_number_sync(), sentinel);
    }
  }
  {
    auto sentinel = LocalizedText{"en", "test"};
    auto wr = obj.try_write_effective_display_name_sync(sentinel);
    EXPECT_TRUE(wr.is_good()) << "effective_display_name write failed: 0x" << std::hex
                              << wr.status_code().as_uint32();
    auto rd = obj.try_read_effective_display_name_sync();
    EXPECT_TRUE(rd.is_good()) << "effective_display_name read failed: 0x" << std::hex
                              << rd.status_code().as_uint32();
    if (wr.is_good() && rd.is_good())
    {
      EXPECT_EQ(rd.value(), sentinel);
      // Throwing variants (no try_ prefix): same write+read
      // round-trip. Only reached when the try_ variants are good,
      // so these never throw here; a regression that broke the
      // throwing path would surface as a thrown UaException.
      obj.write_effective_display_name_sync(sentinel);
      EXPECT_EQ(obj.read_effective_display_name_sync(), sentinel);
    }
  }
}

TEST_F(GeneratedInstanceTypeTests, FiniteStateVariable_UnattachedAccessorsFailClosed)
{
  FiniteStateVariable obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_id_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_id_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_name_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_name_sync(QualifiedName{0, "test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_number_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_number_sync(uint32_t{123456}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_effective_display_name_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_effective_display_name_sync(LocalizedText{"en", "test"}).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_id_property_sync().status_code();
  (void)obj.try_name_property_sync().status_code();
  (void)obj.try_number_property_sync().status_code();
  (void)obj.try_effective_display_name_property_sync().status_code();
}

