TEST_F(GeneratedInstanceTypeTests, KeyCredentialConfiguration_UnattachedAccessorsFailClosed)
{
  KeyCredentialConfiguration obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_resource_uri_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_resource_uri_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_profile_uri_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_profile_uri_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_endpoint_urls_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_endpoint_urls_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_credential_id_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_credential_id_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_service_status_sync().status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_resource_uri_property_sync().status_code();
  (void)obj.try_profile_uri_property_sync().status_code();
  (void)obj.try_endpoint_urls_property_sync().status_code();
  (void)obj.try_credential_id_property_sync().status_code();
  (void)obj.try_service_status_property_sync().status_code();

  // Method-accessor lookups.
  (void)obj.try_get_encrypting_key_method_sync().status_code();
  (void)obj.try_update_credential_method_sync().status_code();
  (void)obj.try_delete_credential_method_sync().status_code();
}

