TEST_F(GeneratedInstanceTypeTests, KeyCredentialUpdatedAuditEvent_CreateAndAttach)
{
  auto createResult = KeyCredentialUpdatedAuditEvent::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestKeyCredentialUpdatedAuditEvent"},
    {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = KeyCredentialUpdatedAuditEvent::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = KeyCredentialUpdatedAuditEvent::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = KeyCredentialUpdatedAuditEvent::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestKeyCredentialUpdatedAuditEventThrowing"},
    {});
  (void)created2;
}

