TEST_F(GeneratedInstanceTypeTests, NamespaceMetadata_UnattachedAccessorsFailClosed)
{
  NamespaceMetadata obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_namespace_uri_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_namespace_uri_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_namespace_version_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_namespace_version_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_namespace_publication_date_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_namespace_publication_date_sync(DateTime::now()).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_is_namespace_subset_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_is_namespace_subset_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_static_string_node_id_pattern_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_static_string_node_id_pattern_sync(String{"test"}).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_namespace_uri_property_sync().status_code();
  (void)obj.try_namespace_version_property_sync().status_code();
  (void)obj.try_namespace_publication_date_property_sync().status_code();
  (void)obj.try_is_namespace_subset_property_sync().status_code();
  (void)obj.try_static_node_id_types_property_sync().status_code();
  (void)obj.try_static_numeric_node_id_range_property_sync().status_code();
  (void)obj.try_static_string_node_id_pattern_property_sync().status_code();
  (void)obj.try_default_role_permissions_property_sync().status_code();
  (void)obj.try_default_user_role_permissions_property_sync().status_code();
  (void)obj.try_default_access_restrictions_property_sync().status_code();
  (void)obj.try_configuration_version_property_sync().status_code();
  (void)obj.try_model_version_property_sync().status_code();

  // Typed child-object / data-variable handle lookups.
  (void)obj.try_namespace_file_sync().status_code();
}

