TEST_F(GeneratedInstanceTypeTests, NonExclusiveLevelAlarm_CreateAndAttach)
{
  auto createResult = NonExclusiveLevelAlarm::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestNonExclusiveLevelAlarm"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = NonExclusiveLevelAlarm::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = NonExclusiveLevelAlarm::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = NonExclusiveLevelAlarm::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestNonExclusiveLevelAlarmThrowing"},
    {});
  (void)created2;
}

