TEST_F(GeneratedInstanceTypeTests, NonExclusiveLimitAlarm_CreateAndAttach)
{
  auto createResult = NonExclusiveLimitAlarm::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestNonExclusiveLimitAlarm"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = NonExclusiveLimitAlarm::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = NonExclusiveLimitAlarm::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = NonExclusiveLimitAlarm::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestNonExclusiveLimitAlarmThrowing"},
    {});
  (void)created2;
}

