TEST_F(GeneratedInstanceTypeTests, OffNormalAlarm_DefaultConstruction)
{
  OffNormalAlarm obj;
  (void)obj;
}

TEST_F(GeneratedInstanceTypeTests, OffNormalAlarm_CreateAndAttach)
{
  auto createResult = OffNormalAlarm::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestOffNormalAlarm"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = OffNormalAlarm::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = OffNormalAlarm::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = OffNormalAlarm::create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestOffNormalAlarmThrowing"}, {});
  (void)created2;
}

