TEST_F(GeneratedInstanceTypeTests, Role_UnattachedAccessorsFailClosed)
{
  Role obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_applications_exclude_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_applications_exclude_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_applications_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_applications_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_endpoints_exclude_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_endpoints_exclude_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_custom_configuration_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_custom_configuration_sync(true).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_identities_property_sync().status_code();
  (void)obj.try_applications_exclude_property_sync().status_code();
  (void)obj.try_applications_property_sync().status_code();
  (void)obj.try_endpoints_exclude_property_sync().status_code();
  (void)obj.try_endpoints_property_sync().status_code();
  (void)obj.try_custom_configuration_property_sync().status_code();

  // Method-accessor lookups.
  (void)obj.try_add_identity_method_sync().status_code();
  (void)obj.try_remove_identity_method_sync().status_code();
  (void)obj.try_add_application_method_sync().status_code();
  (void)obj.try_remove_application_method_sync().status_code();
  (void)obj.try_add_endpoint_method_sync().status_code();
  (void)obj.try_remove_endpoint_method_sync().status_code();
}

