TEST_F(GeneratedInstanceTypeTests, SerializationEntity_Children)
{
  InstantiationOptions optionsWithAllOptionals;
  optionsWithAllOptionals.optionalChildFilter = [](const ChildFilterInfo&)
  {
    return true;
  };
  auto createResult = SerializationEntity::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestSerializationEntityKids"},
    optionsWithAllOptionals);
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();

  // Typed child-object / data-variable accessors.
  {
    auto r = obj.try_serialized_data_sync();
    (void)r.status_code();
    try
    {
      (void)obj.serialized_data_sync();
    }
    catch (...)
    {}
  }

  // Method handler registration + method-accessor lookup.
  {
    SerializationEntity::ConfigureSerializationHandler handler =
      [](const MethodCall&, const SerializationEntity::ConfigureSerializationInputArguments&)
      -> MethodResult<SerializationEntity::ConfigureSerializationOutputArguments>
    {
      return SerializationEntity::ConfigureSerializationOutputArguments{};
    };
    auto sh = obj.try_set_configure_serialization_handler_sync(std::move(handler));
    (void)sh.status_code();
    SerializationEntity::ConfigureSerializationAsyncHandler asyncHandler =
      [](const MethodCall&,
        const SerializationEntity::ConfigureSerializationInputArguments&,
        MethodResultCallback<SerializationEntity::ConfigureSerializationOutputArguments>
          complete)
    {
      complete(SerializationEntity::ConfigureSerializationOutputArguments{});
    };
    auto ash = obj.try_set_configure_serialization_handler_sync(std::move(asyncHandler));
    (void)ash.status_code();
    auto ma = obj.try_configure_serialization_method_sync();
    (void)ma.status_code();
  }
}

TEST_F(GeneratedInstanceTypeTests, SerializationEntity_UnattachedAccessorsFailClosed)
{
  SerializationEntity obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_include_reference_types_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_include_reference_types_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_exclude_reference_types_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_exclude_reference_types_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_serialization_depth_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_serialization_depth_sync(uint16_t{12345}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_consider_sub_element_serialization_properties_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_consider_sub_element_serialization_properties_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_custom_meta_data_ref_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_custom_meta_data_ref_sync(NodeId{1234}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_include_status_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_include_status_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_include_source_timestamp_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_include_source_timestamp_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_include_dictionary_reference_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_include_dictionary_reference_sync(true).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_include_reference_types_property_sync().status_code();
  (void)obj.try_exclude_reference_types_property_sync().status_code();
  (void)obj.try_serialization_depth_property_sync().status_code();
  (void)obj.try_consider_sub_element_serialization_properties_property_sync().status_code();
  (void)obj.try_custom_meta_data_properties_property_sync().status_code();
  (void)obj.try_custom_meta_data_ref_property_sync().status_code();
  (void)obj.try_include_status_property_sync().status_code();
  (void)obj.try_include_source_timestamp_property_sync().status_code();
  (void)obj.try_include_dictionary_reference_property_sync().status_code();

  // Typed child-object / data-variable handle lookups.
  (void)obj.try_serialized_data_sync().status_code();

  // Method-accessor lookups.
  (void)obj.try_configure_serialization_method_sync().status_code();
}

