TEST_F(GeneratedInstanceTypeTests, ServerCapabilities_CreateAndAttach)
{
  auto createResult = ServerCapabilities::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestServerCapabilities"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = ServerCapabilities::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = ServerCapabilities::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = ServerCapabilities::create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestServerCapabilitiesThrowing"}, {});
  (void)created2;
}

