TEST_F(GeneratedInstanceTypeTests, ServerObject_UnattachedAccessorsFailClosed)
{
  ServerObject obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_server_array_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_server_array_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_namespace_array_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_namespace_array_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_service_level_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_service_level_sync(uint8_t{123}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_auditing_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_auditing_sync(true).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_estimated_return_time_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_estimated_return_time_sync(DateTime::now()).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_server_array_property_sync().status_code();
  (void)obj.try_namespace_array_property_sync().status_code();
  (void)obj.try_uris_version_property_sync().status_code();
  (void)obj.try_service_level_property_sync().status_code();
  (void)obj.try_auditing_property_sync().status_code();
  (void)obj.try_estimated_return_time_property_sync().status_code();
  (void)obj.try_local_time_property_sync().status_code();

  // Typed child-object / data-variable handle lookups.
  (void)obj.try_server_status_sync().status_code();
  (void)obj.try_server_capabilities_sync().status_code();
  (void)obj.try_server_diagnostics_sync().status_code();
  (void)obj.try_vendor_server_info_sync().status_code();
  (void)obj.try_server_redundancy_sync().status_code();
  (void)obj.try_namespaces_sync().status_code();

  // Method-accessor lookups.
  (void)obj.try_get_monitored_items_method_sync().status_code();
  (void)obj.try_resend_data_method_sync().status_code();
  (void)obj.try_set_subscription_durable_method_sync().status_code();
  (void)obj.try_request_server_state_change_method_sync().status_code();
}

