TEST_F(GeneratedInstanceTypeTests, SystemOffNormalAlarm_CreateAndAttach)
{
  auto createResult = SystemOffNormalAlarm::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestSystemOffNormalAlarm"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = SystemOffNormalAlarm::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = SystemOffNormalAlarm::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = SystemOffNormalAlarm::create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestSystemOffNormalAlarmThrowing"}, {});
  (void)created2;
}

