TEST_F(GeneratedInstanceTypeTests, TemporaryFileTransfer_CreateAndAttach)
{
  auto createResult = TemporaryFileTransfer::try_create_sync(
    *addressSpace, NodeId{ObjectId::ObjectsFolder}, QualifiedName{0, "TestTemporaryFileTransfer"}, {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();
  auto attachResult = TemporaryFileTransfer::try_attach_sync(*addressSpace, obj.node_id());
  EXPECT_TRUE(attachResult.is_good());
  // Throwing-variant create/attach (no try_ prefix): same contract,
  // .value()-unwrapping. On the valid fixture these never throw.
  auto attached = TemporaryFileTransfer::attach_sync(*addressSpace, obj.node_id());
  (void)attached;
  auto created2 = TemporaryFileTransfer::create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestTemporaryFileTransferThrowing"},
    {});
  (void)created2;
}

