TEST_F(GeneratedInstanceTypeTests, TemporaryFileTransfer_Method_CloseAndCommit)
{
  auto createResult = TemporaryFileTransfer::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestTemporaryFileTransferMethodCloseAndCommit"},
    {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();

  std::atomic<bool> handlerCalled{false};
  TemporaryFileTransfer::CloseAndCommitHandler handler =
    [&](const MethodCall&, const TemporaryFileTransfer::CloseAndCommitInputArguments& in)
    -> MethodResult<TemporaryFileTransfer::CloseAndCommitOutputArguments>
  {
    handlerCalled = true;
    auto expected_in_FileHandle = uint32_t{123456};
    EXPECT_EQ(in.fileHandle, expected_in_FileHandle);
    TemporaryFileTransfer::CloseAndCommitOutputArguments out;
    out.completionStateMachine = NodeId{4321};
    return out;
  };

  auto setRes = obj.try_set_close_and_commit_handler_sync(std::move(handler));
  ASSERT_TRUE(setRes.is_good()) << "set handler failed: 0x" << std::hex << setRes.status_code().as_uint32();

  auto maRes = obj.try_close_and_commit_method_sync();
  ASSERT_TRUE(maRes.is_good()) << "method accessor lookup failed: 0x" << std::hex
                               << maRes.status_code().as_uint32();
  auto ma = std::move(maRes).value();

  CallMethodRequest req;
  req.object_id() = obj.node_id();
  req.method_id() = ma.get_node_id();
  req.input_arguments().resize(1);
  req.input_arguments()[0] = Variant{uint32_t{123456}};

  auto callRes = ma.try_call_sync(req);
  ASSERT_TRUE(callRes.is_good()) << "call failed: 0x" << std::hex << callRes.status_code().as_uint32();
  EXPECT_TRUE(handlerCalled.load());
  const auto& outArgs = callRes.value().output_arguments();
  ASSERT_EQ(outArgs.size(), 1u);
  auto expected_out_CompletionStateMachine = NodeId{4321};
  EXPECT_EQ(outArgs[0].as<NodeId>(), expected_out_CompletionStateMachine);
}

