TEST_F(GeneratedInstanceTypeTests, TwoStateDiscrete_Properties)
{
  InstantiationOptions optionsWithAllOptionals;
  optionsWithAllOptionals.optionalChildFilter = [](const ChildFilterInfo&)
  {
    return true;
  };
  auto createResult = TwoStateDiscrete::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestTwoStateDiscreteProps"},
    optionsWithAllOptionals,
    {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();

  // Untyped Property handle lookup - exercises the find-by-browse-name
  // path for every declared property.
  {
    auto h = obj.try_false_state_property_sync();
    (void)h.status_code();
    try
    {
      (void)obj.false_state_property_sync();
    }
    catch (...)
    {}
  }
  {
    auto h = obj.try_true_state_property_sync();
    (void)h.status_code();
    try
    {
      (void)obj.true_state_property_sync();
    }
    catch (...)
    {}
  }
  {
    auto h = obj.try_definition_property_sync();
    (void)h.status_code();
    try
    {
      (void)obj.definition_property_sync();
    }
    catch (...)
    {}
  }
  {
    auto h = obj.try_value_precision_property_sync();
    (void)h.status_code();
    try
    {
      (void)obj.value_precision_property_sync();
    }
    catch (...)
    {}
  }

  // Typed read/write - every property (mandatory + optional) is
  // instantiated by the optional-inclusive create above, so we can
  // assert write+read both succeed and the read returns the sentinel.
  {
    auto sentinel = LocalizedText{"en", "test"};
    auto wr = obj.try_write_false_state_sync(sentinel);
    EXPECT_TRUE(wr.is_good()) << "false_state write failed: 0x" << std::hex << wr.status_code().as_uint32();
    auto rd = obj.try_read_false_state_sync();
    EXPECT_TRUE(rd.is_good()) << "false_state read failed: 0x" << std::hex << rd.status_code().as_uint32();
    if (wr.is_good() && rd.is_good())
    {
      EXPECT_EQ(rd.value(), sentinel);
      // Throwing variants (no try_ prefix): same write+read
      // round-trip. Only reached when the try_ variants are good,
      // so these never throw here; a regression that broke the
      // throwing path would surface as a thrown UaException.
      obj.write_false_state_sync(sentinel);
      EXPECT_EQ(obj.read_false_state_sync(), sentinel);
    }
  }
  {
    auto sentinel = LocalizedText{"en", "test"};
    auto wr = obj.try_write_true_state_sync(sentinel);
    EXPECT_TRUE(wr.is_good()) << "true_state write failed: 0x" << std::hex << wr.status_code().as_uint32();
    auto rd = obj.try_read_true_state_sync();
    EXPECT_TRUE(rd.is_good()) << "true_state read failed: 0x" << std::hex << rd.status_code().as_uint32();
    if (wr.is_good() && rd.is_good())
    {
      EXPECT_EQ(rd.value(), sentinel);
      // Throwing variants (no try_ prefix): same write+read
      // round-trip. Only reached when the try_ variants are good,
      // so these never throw here; a regression that broke the
      // throwing path would surface as a thrown UaException.
      obj.write_true_state_sync(sentinel);
      EXPECT_EQ(obj.read_true_state_sync(), sentinel);
    }
  }
  {
    auto sentinel = String{"test"};
    auto wr = obj.try_write_definition_sync(sentinel);
    EXPECT_TRUE(wr.is_good()) << "definition write failed: 0x" << std::hex << wr.status_code().as_uint32();
    auto rd = obj.try_read_definition_sync();
    EXPECT_TRUE(rd.is_good()) << "definition read failed: 0x" << std::hex << rd.status_code().as_uint32();
    if (wr.is_good() && rd.is_good())
    {
      EXPECT_EQ(rd.value(), sentinel);
      // Throwing variants (no try_ prefix): same write+read
      // round-trip. Only reached when the try_ variants are good,
      // so these never throw here; a regression that broke the
      // throwing path would surface as a thrown UaException.
      obj.write_definition_sync(sentinel);
      EXPECT_EQ(obj.read_definition_sync(), sentinel);
    }
  }
  {
    auto sentinel = 1.5;
    auto wr = obj.try_write_value_precision_sync(sentinel);
    EXPECT_TRUE(wr.is_good()) << "value_precision write failed: 0x" << std::hex
                              << wr.status_code().as_uint32();
    auto rd = obj.try_read_value_precision_sync();
    EXPECT_TRUE(rd.is_good()) << "value_precision read failed: 0x" << std::hex
                              << rd.status_code().as_uint32();
    if (wr.is_good() && rd.is_good())
    {
      EXPECT_EQ(rd.value(), sentinel);
      // Throwing variants (no try_ prefix): same write+read
      // round-trip. Only reached when the try_ variants are good,
      // so these never throw here; a regression that broke the
      // throwing path would surface as a thrown UaException.
      obj.write_value_precision_sync(sentinel);
      EXPECT_EQ(obj.read_value_precision_sync(), sentinel);
    }
  }
}

TEST_F(GeneratedInstanceTypeTests, TwoStateDiscrete_UnattachedAccessorsFailClosed)
{
  TwoStateDiscrete obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_false_state_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_false_state_sync(LocalizedText{"en", "test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_true_state_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_true_state_sync(LocalizedText{"en", "test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_definition_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_definition_sync(String{"test"}).status_code().is_bad());
  EXPECT_TRUE(obj.try_read_value_precision_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_value_precision_sync(1.5).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_false_state_property_sync().status_code();
  (void)obj.try_true_state_property_sync().status_code();
  (void)obj.try_definition_property_sync().status_code();
  (void)obj.try_value_precision_property_sync().status_code();
}

