TEST_F(GeneratedInstanceTypeTests, UserManagement_UnattachedAccessorsFailClosed)
{
  UserManagement obj;  // default-constructed: no bound address space

  // Typed value read/write accessors fail closed with a bad status (the
  // !mAddressSpace guard), never a crash, on an unattached handle.
  EXPECT_TRUE(obj.try_read_password_restrictions_sync().status_code().is_bad());
  EXPECT_TRUE(obj.try_write_password_restrictions_sync(LocalizedText{"en", "test"}).status_code().is_bad());

  // Untyped property-handle lookups also run their guard; drain the status
  // (only that they do not crash on an unattached handle is required here).
  (void)obj.try_users_property_sync().status_code();
  (void)obj.try_password_length_property_sync().status_code();
  (void)obj.try_password_options_property_sync().status_code();
  (void)obj.try_password_restrictions_property_sync().status_code();

  // Method-accessor lookups.
  (void)obj.try_add_user_method_sync().status_code();
  (void)obj.try_modify_user_method_sync().status_code();
  (void)obj.try_remove_user_method_sync().status_code();
  (void)obj.try_change_password_method_sync().status_code();
}

TEST_F(GeneratedInstanceTypeTests, UserManagement_Method_RemoveUser)
{
  auto createResult = UserManagement::try_create_sync(*addressSpace,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{0, "TestUserManagementMethodRemoveUser"},
    {});
  ASSERT_TRUE(createResult.is_good());
  auto obj = std::move(createResult).value();

  std::atomic<bool> handlerCalled{false};
  UserManagement::RemoveUserHandler handler =
    [&](const MethodCall&, const UserManagement::RemoveUserInputArguments& in) -> MethodResult<>
  {
    handlerCalled = true;
    auto expected_in_UserName = String{"test"};
    EXPECT_EQ(in.userName, expected_in_UserName);
    return {};
  };

  auto setRes = obj.try_set_remove_user_handler_sync(std::move(handler));
  ASSERT_TRUE(setRes.is_good()) << "set handler failed: 0x" << std::hex << setRes.status_code().as_uint32();

  auto maRes = obj.try_remove_user_method_sync();
  ASSERT_TRUE(maRes.is_good()) << "method accessor lookup failed: 0x" << std::hex
                               << maRes.status_code().as_uint32();
  auto ma = std::move(maRes).value();

  CallMethodRequest req;
  req.object_id() = obj.node_id();
  req.method_id() = ma.get_node_id();
  req.input_arguments().resize(1);
  req.input_arguments()[0] = Variant{String{"test"}};

  auto callRes = ma.try_call_sync(req);
  ASSERT_TRUE(callRes.is_good()) << "call failed: 0x" << std::hex << callRes.status_code().as_uint32();
  EXPECT_TRUE(handlerCalled.load());
}

